-- The vocations' area spells (2026-11-16) are drawn here, not by the server: for every cast the server sends extended
-- opcode 40 to each player who can see it, "id|caster creature id|x|y|z|seed" (id like "sorcerer_1000"), and the client
-- plays the spell's design from designs.lua (SPELLFX_DESIGNS, generated by ForgottenL/tools/gen_vocation_spells.py from
-- the map editor's Spell Creator). The player chooses (Options > Graphics) whether to see his own spells and other
-- players' spells, and how transparent each are.
--
-- The design player is the map editor's exported script (RME-ZONES source/spell_design.cpp exportLua) with the same timing
-- and the same random rules; the random numbers come from the message's seed (a small generator of this module, never
-- math.randomseed), so every player sees the same cast.
--
-- Ids: the effects and missiles of the designs are SERVER ids; the dat (and the wire) use server id + 1. Transparency is
-- per thing type, so the client draws its own spells with one copy of each effect/missile and other players' spells with
-- another (appended to Tibia.dat by ForgottenL/tools/gen_spellfx_copies.py; SPELLFX_OWN / SPELLFX_OTHER map a server id to
-- the DAT id of its copy). Without copies (an older dat) the spells are drawn with the originals and the transparency
-- options do nothing, since the originals are shared with every other effect of the game.

local OPCODE = 40
local OTML_FILE = '/spellfx_opacity.otml' -- in the write dir, loaded with g_things.loadOtml
local MAX_MESSAGE = 128
local MAX_WORK_PER_CAST = 3000 -- scheduled events + things drawn by one cast
local MAX_PENDING = 12000 -- scheduled events of every cast together: past this new casts are not drawn
local MAX_REPEATS = 50
local MAX_TIME = 20000 -- no part of a cast is scheduled later than this (ms)
local MAX_OFFSET = 30 -- tiles farther from the caster than this are not drawn
local OPACITY_DELAY = 150 -- a slider being dragged writes the otml once it stops

-- the options and their defaults (also in client_options' defaultOptions): shown, 0 percent transparency
local OPTION_DEFAULTS = {
  showOwnSpellEffects = true,
  showOtherSpellEffects = true,
  ownSpellEffectsTransparency = 0,
  otherSpellEffectsTransparency = 0,
}
local MAX_TRANSPARENCY = 90

local options = {}
local generation = 0 -- a game end or a module reload drops every cast in flight
local pending = 0
local limits = {effects = 0, missiles = 0} -- the highest dat id of each category of the loaded dat
local opacityEvent = nil
local appliedOpacity = nil -- the otml last loaded (nil: load it again)
local errorLogged = false

local function logError(err)
  if not errorLogged then
    errorLogged = true
    g_logger.error('[game_spellfx] ' .. tostring(err))
  end
end

local function safe(fn, ...)
  local ok, err = pcall(fn, ...)
  if not ok then logError(err) end
end

local function clamp(v, low, high)
  v = tonumber(v) or low
  if v ~= v then return low end -- NaN
  return math.max(low, math.min(high, v))
end

-- random numbers ------------------------------------------------------------------------------------------------------

-- Park-Miller "minimal standard" generator: exact in doubles (16807 * 2^31 < 2^53), the same on every client
local function newRandom(seed)
  local s = math.floor(math.abs(tonumber(seed) or 0)) % 2147483646 + 1
  local rnd = {}
  function rnd.float() -- [0, 1), like math.random()
    s = (s * 16807) % 2147483647
    return (s - 1) / 2147483646
  end
  function rnd.int(a, b) -- like math.random(a) and math.random(a, b)
    if b == nil then a, b = 1, a end
    if b <= a then return a end
    return a + math.floor(rnd.float() * (b - a + 1))
  end
  return rnd
end

-- the dat ------------------------------------------------------------------------------------------------------------

local function countThings(category)
  local ok, list = pcall(g_things.getThingTypes, category)
  if ok and type(list) == 'table' then
    return math.max(0, #list - 1) -- index 0 is the null thing
  end
  return 0
end

local function readLimits()
  if g_things.isDatLoaded() then
    limits.effects = countThings(ThingCategoryEffect)
    limits.missiles = countThings(ThingCategoryMissile)
  else
    limits.effects, limits.missiles = 0, 0
  end
end

-- the dat id to draw a design's effect/missile (server id) with, for the caster's side; nil when the dat lacks it
local function datId(kind, serverId, own)
  local copies = own and SPELLFX_OWN or SPELLFX_OTHER
  local copy = type(copies) == 'table' and type(copies[kind]) == 'table' and copies[kind][serverId]
  if copy and copy >= 1 and copy <= limits[kind] then
    return copy
  end
  local id = serverId + 1
  if id >= 1 and id <= limits[kind] then
    return id
  end
  return nil
end

-- the effects and missiles of the copies with the transparency of the options: an otml of thing types (ThingType opacity)
local function opacityOtml()
  local sides = {
    {copies = SPELLFX_OWN, opacity = 1 - clamp(options.ownSpellEffectsTransparency, 0, MAX_TRANSPARENCY) / 100},
    {copies = SPELLFX_OTHER, opacity = 1 - clamp(options.otherSpellEffectsTransparency, 0, MAX_TRANSPARENCY) / 100},
  }
  local sections = {}
  local count = 0
  for _, kind in ipairs({'effects', 'missiles'}) do
    local lines, seen = {}, {}
    for _, side in ipairs(sides) do
      local list = type(side.copies) == 'table' and side.copies[kind]
      if type(list) == 'table' then
        local ids = {}
        for _, copy in pairs(list) do
          copy = tonumber(copy)
          if copy and copy >= 1 and copy <= limits[kind] and not seen[copy] then
            seen[copy] = true
            table.insert(ids, copy)
          end
        end
        table.sort(ids)
        for _, copy in ipairs(ids) do
          table.insert(lines, string.format('  %d\n    opacity: %.2f', copy, side.opacity))
          count = count + 1
        end
      end
    end
    if #lines > 0 then
      table.insert(sections, kind .. '\n' .. table.concat(lines, '\n'))
    end
  end
  if count == 0 then return nil end
  return table.concat(sections, '\n') .. '\n'
end

local function applyOpacity()
  removeEvent(opacityEvent)
  opacityEvent = nil
  if not g_things.isDatLoaded() then return end
  local text = opacityOtml()
  if not text or text == appliedOpacity then return end
  if g_resources.writeFileContents(OTML_FILE, text) and g_things.loadOtml(OTML_FILE) then
    appliedOpacity = text
  end
end

local function scheduleOpacity()
  removeEvent(opacityEvent)
  opacityEvent = scheduleEvent(function() safe(applyOpacity) end, OPACITY_DELAY)
end

-- a new dat (game start, a version change) has every thing at full opacity again
local function onLoadDat()
  safe(function()
    readLimits()
    appliedOpacity = nil
    scheduleOpacity()
  end)
end

-- the options ------------------------------------------------------------------------------------------------------------

local function readOptions()
  for key, default in pairs(OPTION_DEFAULTS) do
    g_settings.setDefault(key, default)
    if type(default) == 'boolean' then
      options[key] = g_settings.getBoolean(key)
    else
      options[key] = clamp(g_settings.getNumber(key), 0, MAX_TRANSPARENCY)
    end
  end
end

-- client_options calls this when one of the four options changes
function refreshOptions()
  safe(readOptions)
  scheduleOpacity()
end

-- where things can be drawn (Map::isAwareOfPosition): an effect elsewhere would create a tile the server never described
local function isAware(pos)
  local c = g_map.getCentralPosition()
  local range = g_map.getAwareRange()
  if not c or not range or not range.width then return false end
  local first, last = 0, 7
  if c.z > 7 then
    first, last = math.max(0, c.z - 2), math.min(15, c.z + 2)
  end
  if pos.z < first or pos.z > last then return false end
  local dz = pos.z - c.z -- seen from the centre's floor, a floor below is one tile down-right per floor
  local x, y = pos.x + dz, pos.y + dz
  local left = math.floor(range.width / 2) - 1
  local top = math.floor(range.height / 2) - 1
  local right, bottom = range.width - 1 - left, range.height - 1 - top
  return x >= c.x - left and x <= c.x + right and y >= c.y - top and y <= c.y + bottom
end

-- the design player ------------------------------------------------------------------------------------------------------

local function spend(cast)
  if cast.work <= 0 then return false end
  cast.work = cast.work - 1
  return true
end

local function later(cast, ms, fn, ...)
  if cast.gen ~= generation then return end
  ms = math.floor(tonumber(ms) or 0)
  if ms <= 0 then
    fn(cast, ...)
    return
  end
  if ms > MAX_TIME or pending >= MAX_PENDING or not spend(cast) then return end
  pending = pending + 1
  local args = {...}
  scheduleEvent(function()
    pending = math.max(0, pending - 1)
    if cast.gen ~= generation or not g_game.isOnline() then return end
    safe(fn, cast, unpack(args))
  end, ms)
end

local function showEffect(cast, serverId, pos)
  local id = datId('effects', serverId, cast.own)
  if not id or not spend(cast) or not isAware(pos) then return end
  local effect = Effect.create()
  effect:setId(id)
  g_map.addThing(effect, pos, -1)
end

local function showMissile(cast, serverId, from, to)
  local id = datId('missiles', serverId, cast.own)
  if not id or not spend(cast) or not (isAware(from) or isAware(to)) then return end
  local missile = Missile.create()
  missile:setId(id)
  missile:setPath(from, to)
  g_map.addThing(missile, from, -1)
end

-- how long the client flies a missile (Missile::setPath), so an effect that waits for it lands with it
local function flight(from, to)
  local dx, dy = to.x - from.x, to.y - from.y
  return math.floor(150 * math.sqrt(math.sqrt(dx * dx + dy * dy)))
end

local function land(cast, layer, pos)
  local effect = tonumber(layer.effect) or -1
  if effect >= 0 then
    showEffect(cast, effect, pos)
  end
end

local function fire(cast, layer, pos)
  local wait = 0
  local missile = tonumber(layer.missile) or -1
  if missile >= 0 then
    local rnd = cast.random
    local spread = clamp(layer.spread, 0, 10)
    local from = cast.caster
    if layer.origin == 'center' then
      from = cast.centre
    elseif layer.origin == 'sky' then
      local sx = pos.x + (tonumber(layer.skyX) or 0) + rnd.int(-spread, spread)
      local sy = pos.y + (tonumber(layer.skyY) or 0) + rnd.int(-spread, spread)
      from = {x = sx, y = sy, z = pos.z}
    elseif layer.origin == 'around' then
      local a = rnd.float() * 2 * math.pi
      local d = math.max(1, spread)
      from = {x = pos.x + math.floor(math.cos(a) * d + 0.5), y = pos.y + math.floor(math.sin(a) * d + 0.5), z = pos.z}
    end
    local to = pos
    if layer.reverse then
      from, to = pos, from
    end
    if from.x ~= to.x or from.y ~= to.y then
      showMissile(cast, missile, from, to)
      if layer.waitMissile and not layer.reverse then
        wait = flight(from, to)
      end
    end
  end
  if wait > 0 then
    later(cast, wait, land, layer, pos)
  else
    land(cast, layer, pos)
  end
end

-- a design's offsets face north; a layer that turns follows the caster's direction
local function turn(dx, dy, dir)
  if dir == East then
    return -dy, dx
  elseif dir == South then
    return -dx, -dy
  elseif dir == West then
    return dy, -dx
  end
  return dx, dy
end

local function play(cast, layer)
  local rnd = cast.random
  local tiles = layer.tiles
  local order = {}
  for i, t in ipairs(tiles) do
    order[i] = tonumber(t[3]) or 0
  end
  if layer.random then
    for i = #order, 2, -1 do
      local j = rnd.int(i)
      order[i], order[j] = order[j], order[i]
    end
  end
  local chance = tonumber(layer.chance) or 100
  local step = tonumber(layer.step) or 0
  local centre = cast.centre
  for i, t in ipairs(tiles) do
    if chance >= 100 or rnd.int(100) <= chance then
      local dx, dy = tonumber(t[1]) or 0, tonumber(t[2]) or 0
      if layer.turns then
        dx, dy = turn(dx, dy, cast.dir)
      end
      if math.abs(dx) <= MAX_OFFSET and math.abs(dy) <= MAX_OFFSET then
        local pos = {x = centre.x + dx, y = centre.y + dy, z = centre.z}
        if not layer.sight or (dx == 0 and dy == 0) or g_map.isSightClear(centre, pos, false) then
          later(cast, order[i] * step, fire, layer, pos)
        end
      end
    end
    if cast.work <= 0 then return end
  end
end

-- the message ------------------------------------------------------------------------------------------------------------

local function onSpellFx(protocol, opcode, buffer)
  if type(buffer) ~= 'string' or #buffer > MAX_MESSAGE or not g_game.isOnline() then return end
  local parts = buffer:split('|')
  if #parts < 6 then return end
  local design = type(SPELLFX_DESIGNS) == 'table' and SPELLFX_DESIGNS[parts[1]]
  if type(design) ~= 'table' then return end
  local casterId = tonumber(parts[2])
  local x, y, z = tonumber(parts[3]), tonumber(parts[4]), tonumber(parts[5])
  if not casterId or not x or not y or not z then return end
  if x < 0 or x > 65535 or y < 0 or y > 65535 or z < 0 or z > 15 then return end
  x, y, z = math.floor(x), math.floor(y), math.floor(z)

  local player = g_game.getLocalPlayer()
  local own = player ~= nil and player:getId() == casterId
  if own and not options.showOwnSpellEffects then return end
  if not own and not options.showOtherSpellEffects then return end
  if pending >= MAX_PENDING then return end

  local centre = {x = x, y = y, z = z}
  local caster = g_map.getCreatureById(casterId)
  local cast = {gen = generation, own = own, centre = centre, caster = centre, random = newRandom(parts[6]),
                dir = caster and caster:getDirection() or North, work = MAX_WORK_PER_CAST}

  for _, layer in ipairs(design) do
    if type(layer) == 'table' and type(layer.tiles) == 'table' then
      local delay = tonumber(layer.delay) or 0
      local interval = tonumber(layer.interval) or 0
      for rep = 0, clamp(layer.repeats or 1, 1, MAX_REPEATS) - 1 do
        later(cast, delay + rep * interval, play, layer)
      end
    end
    if cast.work <= 0 then break end
  end
end

-- the module -------------------------------------------------------------------------------------------------------------

local function onGameStart()
  generation = generation + 1
  pending = 0
  readLimits()
  appliedOpacity = nil
  refreshOptions()
end

local function onGameEnd()
  generation = generation + 1
  pending = 0
end

function init()
  safe(readOptions)
  ProtocolGame.registerExtendedOpcode(OPCODE, function(protocol, opcode, buffer) safe(onSpellFx, protocol, opcode, buffer) end)
  connect(g_game, {onGameStart = onGameStart, onGameEnd = onGameEnd})
  connect(g_things, {onLoadDat = onLoadDat})
  if g_game.isOnline() then onGameStart() end
end

function terminate()
  generation = generation + 1
  removeEvent(opacityEvent)
  opacityEvent = nil
  ProtocolGame.unregisterExtendedOpcode(OPCODE)
  disconnect(g_game, {onGameStart = onGameStart, onGameEnd = onGameEnd})
  disconnect(g_things, {onLoadDat = onLoadDat})
end

-- for tests (terminal): modules.game_spellfx.preview('sorcerer_1') plays a design where the player stands, as if the server
-- had sent it (own = false: as another player's cast)
function preview(id, pos, own, seed)
  local player = g_game.getLocalPlayer()
  local caster = own ~= false and player and player:getId() or 0
  pos = pos or (player and player:getPosition())
  if not pos then return end
  safe(onSpellFx, nil, OPCODE, string.format('%s|%d|%d|%d|%d|%d', tostring(id), caster, pos.x, pos.y, pos.z, seed or g_clock.millis()))
end
